package com.barcrawl;

import net.runelite.client.ui.PluginPanel;
import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.HashSet;

public class BarcrawlPanel extends PluginPanel {
    private final JLabel progress = new JLabel("0/0 (0.00%)", SwingConstants.CENTER);
    private final JCheckBox completedBox = new JCheckBox("Completed", true);
    private final JCheckBox incompleteBox = new JCheckBox("Incomplete", true);
    private final JCheckBox drinkBox = new JCheckBox("Drink", true);
    private final JCheckBox foodBox = new JCheckBox("Food", true);



    private final JPanel listPanel = new JPanel();
    private int completedCount = 0;
    private int totalCount = 0;

    private Set<Integer> allConsumables;
    private Set<Integer> consumedItems;
    private Map<Integer, String> itemNames;
    private Set<Integer> foodItems;
    private Set<Integer> drinkItems;

    public BarcrawlPanel() {
        setLayout(new BorderLayout());

        JPanel header = new JPanel();
        header.setLayout(new BorderLayout());

        progress.setFont(progress.getFont().deriveFont(Font.BOLD, 16f));
        progress.setBorder(BorderFactory.createEmptyBorder(8, 5, 8, 5));
        header.add(progress, BorderLayout.NORTH);

        JPanel filters = new JPanel(new GridLayout(2, 2));
        filters.add(completedBox);
        filters.add(incompleteBox);
        filters.add(drinkBox);
        filters.add(foodBox);


        header.add(filters, BorderLayout.CENTER);

        header.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, Color.DARK_GRAY));
        add(header, BorderLayout.NORTH);

        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));

        JScrollPane scrollPane = new JScrollPane(listPanel);

        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setBorder(null);

        add (scrollPane, BorderLayout.CENTER);

        incompleteBox.addActionListener(e -> refreshList());
        completedBox.addActionListener(e -> refreshList());
        foodBox.addActionListener(e -> refreshList());
        drinkBox.addActionListener(e -> refreshList());
    }

    @Override
    public Dimension getPreferredSize() {
        Dimension parentSize = getParent() != null ? getParent().getSize() : super.getPreferredSize();

        int width = parentSize.width > 0 ? parentSize.width : 250;
        int height = parentSize.height > 0 ? parentSize.height : 500;

        return new Dimension(width, height);
    }

    public void updateList(
            Set<Integer> allConsumables,
            Set<Integer> consumedItems,
            Map<Integer, String> itemNames,
            Set<Integer> foodItems,
            Set<Integer> drinkItems)
    {
        this.allConsumables = allConsumables;
        this.consumedItems = consumedItems;
        this.itemNames = itemNames;
        this.foodItems = foodItems;
        this.drinkItems = drinkItems;

        SwingUtilities.invokeLater(this::refreshList);
    }
    private static final Set<Integer> EXCLUDED_CONSUMABLES = Set.of(
            739, 756, // Cadava potion, bravery potion
            1582, // Blamish oil
            2245, 2098, 2096, 2094, 2100, 2197, 2173, // Odd gnome foods
            4559, 4563, 4562, 4560, // Deep blue, green, red, white sweets
            11205,  // Shrunk ogleroot
            13413, 13403, 13412, 13409, 13414, 13418, // Servery foods
            28383, 11204,  // Strange potion, shrink-me-quick
            28388, 25812, 25813, // Strangler serum, sulphur, shielding potion
            26916, 26927, // Special hot sauce, sounds great, melted easter egg
            27485, 27561, 27562, // Light beer, mulled pine, bruised banana..
            33802, 33820, 31174, 25958, // Mysterious jerky, smelly kebab, corrupted shark, paddlefish
            33819, // Jar of congealed blood, gross.
            29950, 29969, // Principum red, Xochipaltic rosé
            29784, // Araxyte venom sac
            24774, // Blood pint
            22430, // Bloody bracer
            26920, // Big bucket of camel milk
            31856, // Bottle of crystal clear water
            33128, 33130, // Milk sample
            2251, 2257, 2261, 2263, 2265, 2267, 2269, 2271, 2273, 2275, 2279, // Unfinished battas
            2179, 2181, 2183, 2189, 2193, // Unfinished bowls
            2042, 2044, 2046, 2050, 2052, 2056,// Unfinished cocktails
            2058, 2060, 2062, 2066, 2068, 2070, 2072, 2076, 2078, 2082, 2086, 2088, 2090, 2207, 2211, 2215, // Unfinished crunchy
            7943, 7942, 337, 6202, 6206, 21293 // Fresh monkfish, giant carp, fishlike thing, infernal eel,

    );

    private void refreshList() {

        if (allConsumables == null || consumedItems == null || itemNames == null) {
            return;
        }
        Set<String> consumedNames = new HashSet<>();

        for (int id : consumedItems) {
            String name = itemNames.get(id);
            if (name != null) {
                consumedNames.add(name);
            }
        }
        listPanel.removeAll();

        List<Integer> sortedItems = new ArrayList<>(allConsumables);
        sortedItems.sort(Comparator.comparing(id -> itemNames.getOrDefault(id, "")));

        Set<String> displayedNames = new HashSet<>();

        int completed = 0;
        int total = 0;

        for (int itemId : sortedItems) {
            String itemName = itemNames.get(itemId);

            if (itemName == null) {
                continue;
            }

            if (EXCLUDED_CONSUMABLES.contains(itemId)) {
                continue;
            }

            if (!displayedNames.add(itemName)) {
                continue;
            }

            total++;

            boolean unlocked = consumedNames.contains(itemName);

            boolean isFood = foodItems != null && foodItems.contains(itemId);
            boolean isDrink = drinkItems != null && drinkItems.contains(itemId);

            if (unlocked) {
                completed++;
            }


            if (unlocked && !completedBox.isSelected()) {
                continue;
            }
            if (!unlocked && !incompleteBox.isSelected()) {
                continue;
            }
            if (isFood && !foodBox.isSelected()) {
                continue;
            }
            if (isDrink && !drinkBox.isSelected()) {
                continue;
            }

            JLabel label = new JLabel((unlocked ? "✓ " : "✗ ") + itemName);

            label.setForeground(unlocked ? new Color(0, 200, 0) : Color.LIGHT_GRAY);
            label.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 8));
            label.setAlignmentX(Component.LEFT_ALIGNMENT);
            listPanel.add(label);

        }

        completedCount = completed;
        totalCount = total;

        double percentage = total == 0 ? 0 : (completed * 100.00 / total);
        progress.setText(completed + "/" + total + " (" + String.format("%.2f", percentage) + "%)");
        if (completed == total) {
            progress.setForeground(new Color(0, 200, 0));
            progress.setText(
                    "<html><div style='text-align: center;'>" + completed + "/" + total + " (" + String.format("%.2f", percentage) + "%)" + "<br>" + "You completed Barcrawl Extreme! Good job! \uD83D\uDE04" + "</div></html>"
            );
        }

        listPanel.revalidate();
        listPanel.repaint();
    }
    public int getCompletedCount() {
        return completedCount;
    }

    public int getTotalCount() {
        return totalCount;
    }

}

package com.barcrawl;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

import java.awt.*;

@ConfigGroup("barcrawl")
public interface BarcrawlConfig extends Config
{
	@ConfigItem(
			keyName = "chatMessage",
			name = "Chat Message",
			description = "Show unlock messages in the chat. (Uses 'Game Message' Chat Color')",
			position = 0
	)
	default boolean chatMessage() {
		return true;
	}

	@ConfigItem(
			keyName = "overHead",
			name = "Overhead Message",
			description = "Show unlock messages overhead",
			position = 1
	)
	default boolean overhead() {
		return true;
	}

	@ConfigItem(
		keyName = "overHeadColor",
		name = "Overhead Color",
		description = "Overhead message color",
		position = 5
	)
	default Color overheadColor() {
		return null;
	}

	@Range(min = 1, max = 20)
	@ConfigItem(
			keyName = "sidebarIcon",
			name = "Sidebar Icon Position",
			description = "Position on the sidebar",
			position = 5
	)
	default int sidebarIcon() {
		return 2;
	}
}

package com.barcrawl;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
		name = "Barcrawl",
		description = "A food and drink collection log, drink up!",
		tags = {"collection", "log", "clog", "food", "drink", "barcrawl", "eat", "unlock", "kalil"}
)

public class BarcrawlPlugin extends Plugin {
	private static final String CONFIG_GROUP = "barCrawl";
	private static final String CONFIG_KEY = "consumedItems";

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BarcrawlConfig config;

	private BarcrawlPanel panel;
	private NavigationButton navButton;

	private final Set<Integer> consumedItems = new HashSet<>();
	private final Set<Integer> allConsumables = new HashSet<>();

	private final Map<Integer, String> itemNames = new HashMap<>();
	private final Set<Integer> foodItems = new HashSet<>();
	private final Set<Integer> drinkItems = new HashSet<>();
	private final Set<String> consumedNames = new HashSet<>();


	private boolean consumablesLoaded;

	@Override
	protected void startUp() throws Exception {

		navBuilder();
		loadCharacterData();
		SwingUtilities.invokeLater(this::updatePanel);
		consumablesLoaded = false;

	}

	@Override
	protected void shutDown() throws Exception {
		if (navButton != null) {
			clientToolbar.removeNavigation(navButton);
		}
	}

	private void navBuilder() {
		panel = new BarcrawlPanel();
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/beericon.png");
		navButton = NavigationButton.builder()
				.tooltip("Barcrawl Extreme")
				.icon(icon)
				.priority(config.sidebarIcon())
				.panel(panel)
				.build();
		clientToolbar.addNavigation(navButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGGED_IN) {
			loadCharacterData();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN) {
			consumablesLoaded = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (consumablesLoaded) {
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN) {
			return;
		}

		for (int itemId = 0; itemId < client.getItemCount(); itemId++) {
			ItemComposition item = client.getItemDefinition(itemId);

			String[] actions = item.getInventoryActions();

			if (actions == null) {
				continue;
			}

			boolean isFood = false;
			boolean isDrink = false;

			for (String action : actions) {
				if ("Eat".equalsIgnoreCase(action)) {
					isFood = true;
				}

				if ("Drink".equalsIgnoreCase(action)) {
					isDrink = true;
				}
			}

			if (!isFood && !isDrink) {
				continue;
			}

			if (item.getNote() != -1 || item.getPlaceholderTemplateId() != -1) {
				continue;
			}
			allConsumables.add(itemId);
			itemNames.put(itemId, item.getName());

			if (isFood) {
				foodItems.add(itemId);
			}

			if (isDrink) {
				drinkItems.add(itemId);
			}
		}

		for (int itemId : consumedItems) {
			String itemName = itemNames.get(itemId);
			if (itemName != null) {
				consumedNames.add(itemName);
			}
		}

		consumablesLoaded = true;
		updatePanel();

	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (!event.isItemOp()) {
			return;
		}

		String option = event.getMenuOption();

		if (!"Eat".equalsIgnoreCase(option) && !"Drink".equalsIgnoreCase(option))
		{
			return;
		}

		int itemId = event.getItemId();

		if (itemId <= 0) {
			return;
		}

		ItemComposition item = client.getItemDefinition(itemId);

		if (!allConsumables.contains(itemId)) {
			return;
		}
		if (!consumedItems.add(itemId)) {
			return;
		}


		String itemName = item.getName();
		boolean wasAlreadyCollected = !consumedNames.add(itemName);

		int unlocked = panel.getCompletedCount();
		int total = panel.getTotalCount();

		if (!wasAlreadyCollected) {
			unlocked++;
		}

		String consumeType = "Eat".equalsIgnoreCase(option) ? "Food" : "Drink";
		String message = "<col=" + getColorHex(config.overheadColor()) + ">" + consumeType + " collected: " + item.getName() + " (" + unlocked + "/" + total + ")" + "</col>";
		Player player = client.getLocalPlayer();
		if (player != null) {
			if (unlocked == total){
				message = message + "!!!";
			}
			if (config.overhead()){
				player.setOverheadText(message);
				player.setOverheadCycle(360);
			}
			if (config.chatMessage()){
				client.addChatMessage(ChatMessageType.CONSOLE, player.getName(), consumeType + " collected: " + item.getName() + " (" + unlocked + "/" + total + ")", null);
			}
		}
		saveCharacterData(itemId);
		updatePanel();
	}

	private void loadCharacterData() {
		consumedItems.clear();

		String savedItems = configManager.getRSProfileConfiguration(
				CONFIG_GROUP,
				CONFIG_KEY
		);

		if (savedItems != null && !savedItems.isEmpty()) {
			for (String id : savedItems.split(",")) {
				try {
					consumedItems.add(Integer.parseInt(id));
				}
				catch (NumberFormatException ignored) {
				}
			}
		}
		updatePanel();
	}

	private void saveCharacterData(int itemId) {
		String savedItems = configManager.getRSProfileConfiguration(
				CONFIG_GROUP,
				CONFIG_KEY
		);

		String data = savedItems == null || savedItems.isEmpty() ? String.valueOf(itemId) : savedItems + "," + itemId;

		configManager.setRSProfileConfiguration(
				CONFIG_GROUP,
				CONFIG_KEY,
				data
		);
	}

	private void updatePanel() {
		if (panel != null && !allConsumables.isEmpty()) {
			panel.updateList(
					allConsumables,
					consumedItems,
					itemNames,
					foodItems,
					drinkItems
			);
		}
	}

	private String getColorHex(Color color) {
		if (color == null) {
			return null;
		}
		return String.format("%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}

	@Provides
	BarcrawlConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(BarcrawlConfig.class);
	}
}
